import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.KafkaException;
import org.apache.kafka.common.TopicPartition;
import java.time.Duration;
import java.util.*;

public class ExactlyOnceKafkaLoop {
    public static void main(String[] args) {
        // Producer：幂等 + 事务
        Properties pp = new Properties();
        pp.put("bootstrap.servers", "localhost:9092");
        pp.put("acks", "all");
        pp.put("enable.idempotence", "true");          // PID + seq 防重传
        pp.put("transactional.id", "order-pipeline-tx"); // 固定 ID，重启后 fence 旧实例
        pp.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        pp.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        KafkaProducer<String, String> producer = new KafkaProducer<>(pp);
        producer.initTransactions();

        // Consumer：关闭自动提交，只读已提交事务的数据
        Properties cp = new Properties();
        cp.put("bootstrap.servers", "localhost:9092");
        cp.put("group.id", "enrichment-group");
        cp.put("enable.auto.commit", "false");
        cp.put("isolation.level", "read_committed");   // 跳过未提交事务
        cp.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        cp.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        KafkaConsumer<String, String> consumer = new KafkaConsumer<>(cp);
        consumer.subscribe(Collections.singletonList("orders"));

        while (true) {
            ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(500));
            if (records.isEmpty()) continue;

            producer.beginTransaction();
            try {
                Map<TopicPartition, OffsetAndMetadata> offsets = new HashMap<>();
                for (ConsumerRecord<String, String> r : records) {
                    // 业务处理 + 写下游 topic
                    producer.send(new ProducerRecord<>("orders.enriched", r.key(), enrich(r.value())));
                    offsets.put(
                        new TopicPartition(r.topic(), r.partition()),
                        new OffsetAndMetadata(r.offset() + 1));
                }
                // 位移提交与下游写入原子打包
                producer.sendOffsetsToTransaction(offsets, consumer.groupMetadata());
                producer.commitTransaction();
            } catch (KafkaException e) {
                producer.abortTransaction(); // 回滚，下次 poll 从未提交位移重读
            }
        }
    }

    static String enrich(String value) { return value.toUpperCase(); }
}
